import requests
from langchain_core.tools import tool

_API = "https://iam.internal.example.com/v1"


@tool
def set_user_role(user_id: str, role: str) -> str:
    if not user_id or not user_id.strip():
        return "error: user_id is required"
    if role not in ("viewer", "editor", "admin"):
        return "error: role must be viewer, editor, or admin"
    r = requests.put(f"{_API}/users/{user_id}/role", json={"role": role}, timeout=10)
    if r.status_code == 404:
        return "error: user not found"
    r.raise_for_status()
    return f"role for {user_id} set to {role}"
